91	      const service = createService();
92	      expect(service.totalPrice()).toBe(0);
93	    });
94	
95	    it('totalPrice zählt nur Sitzplätze mit zugeordneter Kategorie, summiert korrekt über mehrere Positionen', () => {
96	      const service = createService();
97	      service.setPriceCategories([
98	        { id: 10, name: 'Kategorie A', preis: 25 },
99	        { id: 20, name: 'Kategorie B', preis: 45 }
100	      ]);
101	      service.toggle('A', 1);
102	      service.toggle('C', 5);
103	      expect(service.totalPrice()).toBe(0); // beide ohne Kategorie
104	      service.assignCategory('A', 1, 10);
105	      expect(service.totalPrice()).toBe(25);
106	      service.assignCategory('C', 5, 20);
107	      expect(service.totalPrice()).toBe(70);
