282	    ```typescript
283	    import { Component, inject, signal } from '@angular/core';
284	    import { ActivatedRoute } from '@angular/router';
285	    import { HttpErrorResponse } from '@angular/common/http';
286	    import { forkJoin } from 'rxjs';
287	
288	    import { EventsApiService } from '../../core/api/events-api.service';
289	    import { EventDetail } from '../../core/api/event-detail';
290	    import { SeatMap } from '../../core/api/seat-map';
291	    import { SeatMapGrid } from './seat-map/seat-map';
292	    import { PriceSummary } from './price-summary/price-summary';
293	    import { BookingSelectionService } from './booking-selection.service';
294	
295	    @Component({
296	      selector: 'app-booking',
297	      imports: [SeatMapGrid, PriceSummary],
298	      providers: [BookingSelectionService],
299	      templateUrl: './booking.html',
300	      styleUrl: './booking.scss'
301	    })
302	    export class BookingPage {
303	      private readonly route = inject(ActivatedRoute);
304	      private readonly eventsApi = inject(EventsApiService);
305	      private readonly selection = inject(BookingSelectionService);
306	
307	      readonly seatMap = signal<SeatMap | null>(null);
308	      readonly event = signal<EventDetail | null>(null);
309	      readonly loading = signal(true);
310	      readonly notFound = signal(false);
311	      readonly loadError = signal(false);
312	
313	      constructor() {
314	        const id = Number(this.route.snapshot.paramMap.get('id'));
315	        if (!Number.isInteger(id) || id > 2147483647) {
316	          this.loading.set(false);
317	          this.notFound.set(true);
318	          return;
319	        }
320	
321	        forkJoin({
322	          seatMap: this.eventsApi.getSeatMap(id),
323	          event: this.eventsApi.getEvent(id)
324	        }).subscribe({
325	          next: ({ seatMap, event }) => {
326	            this.seatMap.set(seatMap);
327	            this.event.set(event);
328	            this.selection.setPriceCategories(event.preiskategorien);
329	            this.loading.set(false);
330	          },
331	          error: (err: HttpErrorResponse) => {
332	            this.loading.set(false);
333	            if (err.error?.code === 'EVENT_NOT_FOUND') {
334	              this.notFound.set(true);
335	            } else {
336	              this.loadError.set(true);
337	            }
338	          }
339	        });
340	      }
341	    }
342	    ```
